const TEACHER_RESOURCES=[{"id": "teacher-1", "title": "How to Prepare a Sunday School Lesson", "summary": "Read the passage, identify the big idea, set one or two objectives, choose questions, select one activity, and prepare a practical response."}, {"id": "teacher-2", "title": "Teaching Different Age Groups", "summary": "Younger children need shorter explanations, movement and repetition; teens benefit from discussion, real-life connections and room for questions."}, {"id": "teacher-3", "title": "Managing a Class Well", "summary": "Set clear expectations, use names, vary activities, keep transitions short, and correct behaviour calmly without humiliation."}, {"id": "teacher-4", "title": "Asking Better Questions", "summary": "Use open questions that invite observation, meaning and application rather than only yes/no answers."}, {"id": "teacher-5", "title": "Helping Learners Use the Bible", "summary": "Teach learners how to find books, chapters and verses; let them read references themselves where appropriate."}, {"id": "teacher-6", "title": "Working With Parents", "summary": "Send a short summary of the lesson, memory reference and one family discussion prompt."}, {"id": "teacher-7", "title": "Inclusive Teaching", "summary": "Use clear language, visual aids, repetition, readable fonts and more than one way to participate."}, {"id": "teacher-8", "title": "Safe Ministry Practice", "summary": "Use appropriate adult supervision, transparent communication and church safeguarding procedures."}, {"id": "teacher-9", "title": "Teaching Teens Respectfully", "summary": "Do not force personal disclosure. Give room for questions, disagreement, reflection and trusted-adult support."}, {"id": "teacher-10", "title": "Using Games for Learning", "summary": "Use games to reinforce the lesson rather than replacing the Bible study itself."}, {"id": "teacher-11", "title": "Leading Prayer With Children", "summary": "Use simple, voluntary participation. Avoid pressuring children to pray publicly."}, {"id": "teacher-12", "title": "Reviewing Progress", "summary": "Track attendance, lesson completion, memory references and participation without turning faith into a competition."}, {"id": "teacher-13", "title": "Building a Scope and Sequence", "summary": "Plan lessons across the year so learners encounter Bible story, doctrine, character, spiritual habits and application in a balanced way."}, {"id": "teacher-14", "title": "Using Small Groups Well", "summary": "Use small groups for discussion, memory work and application while keeping questions age-appropriate and avoiding forced disclosure."}, {"id": "teacher-15", "title": "Volunteer Onboarding", "summary": "Give every volunteer a clear role, class expectations, safeguarding guidance, lesson access and a simple first-week checklist."}, {"id": "teacher-16", "title": "Coaching New Teachers", "summary": "Pair new teachers with an experienced leader, observe one lesson, debrief briefly and focus feedback on one or two practical improvements."}, {"id": "teacher-17", "title": "Preparing Substitute Teachers", "summary": "Keep lesson summaries, class routines, contact procedure and activity options easy to find so a substitute can lead calmly."}, {"id": "teacher-18", "title": "Family Take-Home Resources", "summary": "Send one clear summary, Bible reference, discussion question and weekly action instead of overwhelming families with too much material."}, {"id": "teacher-19", "title": "Planning a Ministry Year", "summary": "Map teaching themes, review weeks, special Sundays, volunteer training and family events before the year begins."}, {"id": "teacher-20", "title": "Presentation and Visual Aids", "summary": "Use readable slides, large text, simple images and short on-screen points that support teaching instead of competing with it."}, {"id": "teacher-21", "title": "Supporting Different Learners", "summary": "Offer visual schedules, clear instructions, quiet participation options, repeated directions and flexible ways to respond."}, {"id": "teacher-22", "title": "Using Digital Tools Wisely", "summary": "Use video, quizzes and devices to reinforce learning while keeping the Bible lesson and human relationships central."}, {"id": "teacher-23", "title": "Leader Reflection After Class", "summary": "After teaching, record what learners understood, what confused them, what needs follow-up and what should change next time."}, {"id": "teacher-24", "title": "Building a Volunteer Culture", "summary": "Thank volunteers, provide useful training, communicate early, avoid last-minute surprises and create realistic serving expectations."}];
const FAMILY_PROMPTS=[{"id": "family-1", "question": "What was the main thing you learned today?", "tip": "Let the learner explain in their own words before correcting details."}, {"id": "family-2", "question": "Which person in the story made a wise or unwise choice?", "tip": "Ask what made the choice wise or unwise."}, {"id": "family-3", "question": "What does this lesson teach us about God?", "tip": "Keep the answer connected to the passage."}, {"id": "family-4", "question": "What is one thing we can practise this week?", "tip": "Choose something realistic and specific."}, {"id": "family-5", "question": "Which Bible reference did the class use?", "tip": "Find it together at home."}, {"id": "family-6", "question": "What question do you still have?", "tip": "Treat honest questions as opportunities for learning."}, {"id": "family-7", "question": "Who showed courage in today's lesson?", "tip": "Ask what courage looked like and whether it involved fear."}, {"id": "family-8", "question": "What was one difficult choice in the story?", "tip": "Talk about possible consequences and what wisdom would look like."}, {"id": "family-9", "question": "What is one way our family can practise this lesson?", "tip": "Choose one small action everyone can remember."}, {"id": "family-10", "question": "What did you learn about prayer?", "tip": "Invite an honest response without requiring the learner to pray aloud."}, {"id": "family-11", "question": "Which part of the story surprised you?", "tip": "Use the surprise to revisit the Bible reference together."}, {"id": "family-12", "question": "Who could we encourage or serve this week?", "tip": "Turn the lesson into a simple family action."}];
