const SMALL_GROUPS=[{"id": "sg1", "title": "Observation → Meaning → Response", "audience": "Teens", "steps": ["What happened or was said?", "What does it mean in context?", "What could a faithful response look like?"]}, {"id": "sg2", "title": "Story Retell Circle", "audience": "Kids", "steps": ["Retell one event each.", "Put the events in order.", "Name the lesson's big idea."]}, {"id": "sg3", "title": "Question Box", "audience": "Teens", "steps": ["Allow anonymous lesson questions.", "Group similar questions.", "Answer what you can and note what needs further study."]}, {"id": "sg4", "title": "Character Choices", "audience": "All", "steps": ["Name a choice in the passage.", "Discuss possible alternatives.", "Connect the choice to the lesson theme."]}, {"id": "sg5", "title": "Bible Reference Hunt", "audience": "Kids", "steps": ["Find the book.", "Find the chapter.", "Read a selected verse or section in the class Bible."]}, {"id": "sg6", "title": "Weekly Action Review", "audience": "All", "steps": ["Remember last week's action.", "Share what was learned without pressure.", "Choose one new step."]}];
const TAKE_HOME=[{"id": "take-1", "week": 1, "date": "2026-01-04", "dateLabel": "Sunday, 4 January 2026", "title": "God the Creator", "reference": "Genesis 1–2", "memoryVerse": "Genesis 1:1", "bigIdea": "The Bible opens by introducing God as Creator. Before learners meet Abraham, Moses, David, or the disciples, they need to see that the whole story begins with God, who gives life, order, purpose, and value to creation.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Thank God intentionally for three parts of creation this week.", "prayer": "Lord, help me to recognise You as Creator and King."}, {"id": "take-2", "week": 2, "date": "2026-01-11", "dateLabel": "Sunday, 11 January 2026", "title": "The Fall: When Sin Entered the World", "reference": "Genesis 3", "memoryVerse": "Romans 3:23", "bigIdea": "Genesis 3 explains why a good world contains brokenness, shame, conflict, and separation. The lesson should not end with failure; it should also show that God seeks people even after they sin and begins to unfold His rescue plan.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Identify one temptation that often begins with a lie and write down the truth that counters it.", "prayer": "Father, help me to recognise and reject lies."}, {"id": "take-3", "week": 3, "date": "2026-01-18", "dateLabel": "Sunday, 18 January 2026", "title": "Noah: Faithful in an Unfaithful Generation", "reference": "Genesis 6–9", "memoryVerse": "Genesis 9:13", "bigIdea": "Noah's story is more than an ark and animals. It is a lesson about trusting God when obedience is difficult, taking God's warnings seriously, and remembering that God's covenant purposes continue after judgment.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Do one right thing this week even if others do not join you.", "prayer": "Lord, help me obey You even when it is difficult."}, {"id": "take-4", "week": 4, "date": "2026-01-25", "dateLabel": "Sunday, 25 January 2026", "title": "Abraham: Called to Go", "reference": "Genesis 12:1–9", "memoryVerse": "Genesis 12:2", "bigIdea": "God's call to Abraham introduced a major new stage in the Bible story. Abraham was asked to leave what was familiar and trust God's promise. The lesson shows that faith is not passive agreement; it moves when God calls.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Take one obedient step in an area where you have been delaying.", "prayer": "God, give me courage to obey Your direction."}, {"id": "take-5", "week": 5, "date": "2026-02-01", "dateLabel": "Sunday, 1 February 2026", "title": "Abraham and Isaac: Trusting God's Provision", "reference": "Genesis 22:1–19", "memoryVerse": "Genesis 22:14", "bigIdea": "Genesis 22 is a serious passage about trust, obedience, and God's provision. It should be taught carefully, focusing on Abraham's trust in God, God's intervention, and the truth that God provides what is needed for His purpose.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Name one area where fear makes trust difficult and pray about it.", "prayer": "Lord, help me trust Your character in confusing moments."}, {"id": "take-6", "week": 6, "date": "2026-02-08", "dateLabel": "Sunday, 8 February 2026", "title": "Jacob at Bethel: God Is Present", "reference": "Genesis 28:10–22", "memoryVerse": "Genesis 28:15", "bigIdea": "Jacob was travelling away from home when God met him at Bethel. The story teaches that God's presence is not limited to comfortable places. God can meet people in transition, uncertainty, and lonely seasons.", "talk": "What is the main truth you want to remember from this lesson?", "action": "When you feel uncertain, pause and remind yourself that God is present.", "prayer": "God, remind me that You are with me in unfamiliar situations."}, {"id": "take-7", "week": 7, "date": "2026-02-15", "dateLabel": "Sunday, 15 February 2026", "title": "Joseph: When Dreams Meet Difficulty", "reference": "Genesis 37", "memoryVerse": "Genesis 50:20", "bigIdea": "Joseph's story begins with dreams, family tension, and betrayal. This week helps learners understand that having a God-given future does not mean avoiding hardship, and that pride, jealousy, and poor communication can damage relationships.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Celebrate someone else's success instead of comparing yourself.", "prayer": "Lord, free my heart from jealousy and unhealthy comparison."}, {"id": "take-8", "week": 8, "date": "2026-02-22", "dateLabel": "Sunday, 22 February 2026", "title": "Joseph Forgives His Brothers", "reference": "Genesis 45", "memoryVerse": "Ephesians 4:32", "bigIdea": "Years after his betrayal, Joseph had power over the brothers who had harmed him. Instead of using power for revenge, he chose to reveal himself, preserve life, and move toward reconciliation.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Refuse one act of revenge, gossip, or public embarrassment this week.", "prayer": "Father, heal my heart from bitterness."}, {"id": "take-9", "week": 9, "date": "2026-03-01", "dateLabel": "Sunday, 1 March 2026", "title": "Moses and the Burning Bush: Called by God", "reference": "Exodus 3–4", "memoryVerse": "Exodus 3:12", "bigIdea": "Moses met God while doing ordinary work. His first response included questions and excuses, but God kept bringing the focus back to His presence and purpose. Calling is not based only on confidence; it depends on the One who sends.", "talk": "What is the main truth you want to remember from this lesson?", "action": "List one ability you can use to serve others this week.", "prayer": "God, help me hear Your call clearly."}, {"id": "take-10", "week": 10, "date": "2026-03-08", "dateLabel": "Sunday, 8 March 2026", "title": "The Passover: Rescue and Remembrance", "reference": "Exodus 12", "memoryVerse": "Exodus 12:13", "bigIdea": "The Passover marked a decisive moment in Israel's rescue from Egypt. It teaches about obedience, deliverance, and the importance of remembering what God has done from generation to generation.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Ask an older believer to tell you one story of God's faithfulness.", "prayer": "Lord, thank You for Your saving mercy."}, {"id": "take-11", "week": 11, "date": "2026-03-15", "dateLabel": "Sunday, 15 March 2026", "title": "Crossing the Sea: Stand Firm and Move Forward", "reference": "Exodus 14", "memoryVerse": "Exodus 14:14", "bigIdea": "Israel reached a place where the sea was ahead and Pharaoh's army was behind. Fear spread quickly, but God made a way where the people could not see one. The lesson balances stillness before God with obedient movement.", "talk": "What is the main truth you want to remember from this lesson?", "action": "When fear rises, pause before speaking negatively.", "prayer": "God, calm my heart when fear becomes loud."}, {"id": "take-12", "week": 12, "date": "2026-03-22", "dateLabel": "Sunday, 22 March 2026", "title": "The Ten Commandments: Loving God and Neighbour", "reference": "Exodus 20:1–17", "memoryVerse": "Exodus 20:3", "bigIdea": "The Ten Commandments were given to a people God had already rescued. They show what covenant life looks like: worshiping God alone, honouring what is holy, and treating others with truth, respect, faithfulness, and contentment.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Review one command and ask how it affects your choices today.", "prayer": "Lord, help me love You above everything else."}, {"id": "take-13", "week": 13, "date": "2026-03-29", "dateLabel": "Sunday, 29 March 2026", "title": "Joshua: Be Strong and Courageous", "reference": "Joshua 1", "memoryVerse": "Joshua 1:9", "bigIdea": "Joshua stepped into leadership after Moses, a responsibility that could easily have produced fear. God connected courage with His presence and with careful attention to His word.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Read a short Bible passage before one important decision this week.", "prayer": "God, give me courage rooted in Your presence."}, {"id": "take-14", "week": 14, "date": "2026-04-05", "dateLabel": "Sunday, 5 April 2026", "title": "Jericho: Obedience That Does Not Make Sense at First", "reference": "Joshua 6", "memoryVerse": "Joshua 6:20", "bigIdea": "The plan for Jericho was unusual. Israel's victory did not come from normal military strategy, and the story teaches that trust sometimes requires obedience before the outcome is visible.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Finish one good responsibility you have been tempted to abandon.", "prayer": "Lord, give me patience to obey faithfully."}, {"id": "take-15", "week": 15, "date": "2026-04-12", "dateLabel": "Sunday, 12 April 2026", "title": "Deborah: Courageous Leadership and Teamwork", "reference": "Judges 4–5", "memoryVerse": "Judges 4:14", "bigIdea": "Deborah served as a judge and prophetess during a difficult period in Israel's history. Her story highlights courage, discernment, collaboration, and giving God honour for deliverance.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Encourage someone else instead of trying to do everything alone.", "prayer": "God, make me courageous and wise."}, {"id": "take-16", "week": 16, "date": "2026-04-19", "dateLabel": "Sunday, 19 April 2026", "title": "Gideon: When God Uses the Unlikely", "reference": "Judges 6–7", "memoryVerse": "Judges 6:12", "bigIdea": "Gideon did not begin his story feeling like a hero. He was fearful, questioning, and aware of weakness. God patiently led him and reduced Israel's army so that victory could not be explained by human strength alone.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Do one small courageous action instead of waiting to feel fearless.", "prayer": "Lord, meet me in my weakness."}, {"id": "take-17", "week": 17, "date": "2026-04-26", "dateLabel": "Sunday, 26 April 2026", "title": "Ruth: Faithfulness in Ordinary Life", "reference": "Ruth 1–4", "memoryVerse": "Ruth 1:16", "bigIdea": "Ruth's story contains no dramatic battlefield or palace miracle at the beginning. It shows the beauty of loyalty, hard work, kindness, wise guidance, and God's quiet providence through ordinary choices.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Be dependable in one ordinary responsibility this week.", "prayer": "God, make me faithful in small things."}, {"id": "take-18", "week": 18, "date": "2026-05-03", "dateLabel": "Sunday, 3 May 2026", "title": "Hannah: Honest Prayer and Grateful Worship", "reference": "1 Samuel 1–2", "memoryVerse": "1 Samuel 1:27", "bigIdea": "Hannah's prayer came from deep pain, but she brought that pain to God rather than allowing bitterness to define her. When her prayer was answered, she responded with gratitude and worship.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Set aside five quiet minutes to pray honestly this week.", "prayer": "Lord, teach me to pray honestly."}, {"id": "take-19", "week": 19, "date": "2026-05-10", "dateLabel": "Sunday, 10 May 2026", "title": "Samuel: Learning to Listen to God", "reference": "1 Samuel 3", "memoryVerse": "1 Samuel 3:10", "bigIdea": "Samuel was young when he heard God call his name. He needed Eli's guidance to understand what was happening. The story teaches attentiveness to God and the value of wise spiritual guidance.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Create a short quiet time for Bible reading without distractions.", "prayer": "God, give me a listening heart."}, {"id": "take-20", "week": 20, "date": "2026-05-17", "dateLabel": "Sunday, 17 May 2026", "title": "David and Goliath: Courage That Trusts God", "reference": "1 Samuel 17", "memoryVerse": "1 Samuel 17:47", "bigIdea": "David saw the same giant the army saw, but interpreted the situation differently because he remembered God's faithfulness. His courage came from trust, preparation, and a conviction that the battle ultimately belonged to God.", "talk": "What is the main truth you want to remember from this lesson?", "action": "List one past situation that strengthened your faith.", "prayer": "God, help me remember Your faithfulness."}, {"id": "take-21", "week": 21, "date": "2026-05-24", "dateLabel": "Sunday, 24 May 2026", "title": "David and Jonathan: The Gift of Faithful Friendship", "reference": "1 Samuel 18–20", "memoryVerse": "Proverbs 17:17", "bigIdea": "David and Jonathan's friendship developed in a complicated political situation. Their relationship demonstrates loyalty, honest communication, sacrificial support, and choosing what is right over selfish advantage.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Encourage a friend without making the conversation about yourself.", "prayer": "Lord, help me become a faithful friend."}, {"id": "take-22", "week": 22, "date": "2026-05-31", "dateLabel": "Sunday, 31 May 2026", "title": "Solomon: Ask God for Wisdom", "reference": "1 Kings 3:3–15", "memoryVerse": "1 Kings 3:9", "bigIdea": "When Solomon had the opportunity to ask God for something significant, he asked for wisdom to lead well. The lesson helps learners distinguish wisdom from intelligence, popularity, and simply getting what they want.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Before one decision, ask: What is wise, not only what is easy?", "prayer": "God, give me wisdom beyond my own understanding."}, {"id": "take-23", "week": 23, "date": "2026-06-07", "dateLabel": "Sunday, 7 June 2026", "title": "Elijah on Mount Carmel: Choose Whom You Will Serve", "reference": "1 Kings 18", "memoryVerse": "1 Kings 18:39", "bigIdea": "Israel had become divided in loyalty. Elijah's confrontation on Mount Carmel exposed the emptiness of idolatry and called the people back to wholehearted worship of God.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Identify one thing that competes too strongly for your attention or trust.", "prayer": "Lord, turn my heart away from idols."}, {"id": "take-24", "week": 24, "date": "2026-06-14", "dateLabel": "Sunday, 14 June 2026", "title": "Naaman: Humility Before Healing", "reference": "2 Kings 5", "memoryVerse": "2 Kings 5:15", "bigIdea": "Naaman was powerful and respected, but his need could not be solved by status. He almost rejected Elisha's simple instruction because it offended his expectations. Humility became part of the path to healing and recognition of Israel's God.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Receive one piece of wise correction without becoming defensive.", "prayer": "God, expose pride in my heart."}, {"id": "take-25", "week": 25, "date": "2026-06-21", "dateLabel": "Sunday, 21 June 2026", "title": "Josiah: Returning to God's Word", "reference": "2 Kings 22–23", "memoryVerse": "Psalm 119:105", "bigIdea": "King Josiah lived in a culture that had drifted far from covenant faithfulness. When the Book of the Law was found and read, he allowed God's word to confront him and then led practical reform.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Choose one Bible passage to read carefully more than once this week.", "prayer": "Lord, give me a heart that receives Your word."}, {"id": "take-26", "week": 26, "date": "2026-06-28", "dateLabel": "Sunday, 28 June 2026", "title": "Daniel: Conviction in Babylon", "reference": "Daniel 1", "memoryVerse": "Daniel 1:8", "bigIdea": "Daniel and his friends were young people living inside a powerful foreign culture that wanted to reshape their identity. Daniel chose thoughtful conviction rather than careless compromise or disrespectful rebellion.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Decide one boundary before you are pressured to cross it.", "prayer": "God, give me conviction before pressure comes."}, {"id": "take-27", "week": 27, "date": "2026-07-05", "dateLabel": "Sunday, 5 July 2026", "title": "The Fiery Furnace: Faith That Does Not Bargain With God", "reference": "Daniel 3", "memoryVerse": "Daniel 3:17–18", "bigIdea": "Shadrach, Meshach, and Abednego refused to worship Nebuchadnezzar's image even when the penalty was terrifying. Their faith was remarkable because they trusted God's power without demanding that He rescue them in the exact way they wanted.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Refuse one compromise you know is wrong even if it would be easier.", "prayer": "Lord, strengthen my faith under pressure."}, {"id": "take-28", "week": 28, "date": "2026-07-12", "dateLabel": "Sunday, 12 July 2026", "title": "Daniel in the Lions' Den: Consistent Faith", "reference": "Daniel 6", "memoryVerse": "Daniel 6:23", "bigIdea": "Daniel's enemies could find no corruption in his public work, so they targeted his prayer life. His response was not dramatic performance; he simply continued the faithful pattern he had already practised.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Be dependable in one school, work, church, or home responsibility.", "prayer": "God, make me trustworthy in public and private."}, {"id": "take-29", "week": 29, "date": "2026-07-19", "dateLabel": "Sunday, 19 July 2026", "title": "Esther: Courage for Such a Time as This", "reference": "Esther 4–7", "memoryVerse": "Esther 4:14", "bigIdea": "Esther faced a decision that involved real personal risk. Mordecai helped her see that position and influence carry responsibility. Esther responded with preparation, courage, and wise timing.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Use one area of influence to help someone else.", "prayer": "God, give me courage to use influence well."}, {"id": "take-30", "week": 30, "date": "2026-07-26", "dateLabel": "Sunday, 26 July 2026", "title": "Nehemiah: Prayer, Planning, and Perseverance", "reference": "Nehemiah 1–6", "memoryVerse": "Nehemiah 2:18", "bigIdea": "Nehemiah's leadership combined prayer, careful planning, teamwork, courage, and perseverance under criticism. He did not treat prayer and planning as opposites.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Pray about a responsibility and then write a practical plan.", "prayer": "Lord, teach me to pray and plan faithfully."}, {"id": "take-31", "week": 31, "date": "2026-08-02", "dateLabel": "Sunday, 2 August 2026", "title": "Jonah: God's Compassion Is Wider Than Ours", "reference": "Jonah 1–4", "memoryVerse": "Jonah 4:2", "bigIdea": "Jonah knew that God was merciful, but he did not want that mercy extended to Nineveh. The book exposes how easy it is to desire grace for ourselves while resenting it for people we dislike.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Pray for a person or group you find difficult to care about.", "prayer": "God, correct narrowness and prejudice in my heart."}, {"id": "take-32", "week": 32, "date": "2026-08-09", "dateLabel": "Sunday, 9 August 2026", "title": "The Birth of Jesus: Good News of Great Joy", "reference": "Luke 1–2", "memoryVerse": "Luke 2:11", "bigIdea": "The birth of Jesus brings together promise, humility, worship, and good news. God entered the human story not through worldly display but through a child born in humble circumstances.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Refuse to measure worth only by money, popularity, or appearance.", "prayer": "Jesus, thank You for entering our world."}, {"id": "take-33", "week": 33, "date": "2026-08-16", "dateLabel": "Sunday, 16 August 2026", "title": "Jesus' Baptism and Temptation: Identity Before Testing", "reference": "Matthew 3:13–4:11", "memoryVerse": "Matthew 4:4", "bigIdea": "Before Jesus began public ministry, His baptism publicly affirmed His identity and the wilderness brought testing. The sequence teaches that identity rooted in God is vital when temptation tries to redefine priorities.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Write one truth about your identity that does not depend on popularity.", "prayer": "Father, ground my identity in You."}, {"id": "take-34", "week": 34, "date": "2026-08-23", "dateLabel": "Sunday, 23 August 2026", "title": "Jesus Calls the Disciples: Follow Me", "reference": "Mark 1:16–20", "memoryVerse": "Mark 1:17", "bigIdea": "Jesus' call to the first disciples was personal and purposeful. They were invited not only to learn information, but to follow Jesus and become people who would help others know Him.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Choose one teaching of Jesus to practise deliberately this week.", "prayer": "Jesus, teach me to follow You faithfully."}, {"id": "take-35", "week": 35, "date": "2026-08-30", "dateLabel": "Sunday, 30 August 2026", "title": "Salt and Light: Let Your Life Point to God", "reference": "Matthew 5:13–16", "memoryVerse": "Matthew 5:16", "bigIdea": "Jesus described His followers as salt and light—images that suggest influence, preservation, visibility, and purpose. Christian witness should be seen in character and good works that direct attention to God.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Do one good action without posting it for attention.", "prayer": "Lord, let my life reflect Your goodness."}, {"id": "take-36", "week": 36, "date": "2026-09-06", "dateLabel": "Sunday, 6 September 2026", "title": "The Good Samaritan: Love Crosses Boundaries", "reference": "Luke 10:25–37", "memoryVerse": "Luke 10:27", "bigIdea": "Jesus answered a question about neighbour-love with a story that challenged prejudice and passive religion. The Samaritan became the example because compassion moved him to costly action.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Help one person outside your usual social group.", "prayer": "God, enlarge my compassion."}, {"id": "take-37", "week": 37, "date": "2026-09-13", "dateLabel": "Sunday, 13 September 2026", "title": "The Prodigal Son: Grace That Welcomes Repentance", "reference": "Luke 15:11–32", "memoryVerse": "Luke 15:24", "bigIdea": "The parable of the lost son reveals rebellion, repentance, welcome, and the danger of self-righteousness. Both sons were struggling with the father in different ways, and the father's heart becomes central.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Take responsibility for one wrong action without excuses.", "prayer": "Father, give me a repentant heart."}, {"id": "take-38", "week": 38, "date": "2026-09-20", "dateLabel": "Sunday, 20 September 2026", "title": "Jesus Calms the Storm: Faith in Fear", "reference": "Mark 4:35–41", "memoryVerse": "Mark 4:40", "bigIdea": "The disciples were experienced fishermen, yet the storm overwhelmed them. Jesus' presence did not mean there would be no storm, but His authority changed how the disciples were invited to understand it.", "talk": "What is the main truth you want to remember from this lesson?", "action": "When anxious, name the fear and then pray specifically about it.", "prayer": "Jesus, meet me in my fears."}, {"id": "take-39", "week": 39, "date": "2026-09-27", "dateLabel": "Sunday, 27 September 2026", "title": "Feeding the Five Thousand: Bring What You Have", "reference": "John 6:1–14", "memoryVerse": "John 6:35", "bigIdea": "A large crowd had a real need and the disciples saw an impossible calculation. Jesus used a small available lunch as part of a much larger provision, teaching dependence and generosity.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Offer one small skill, resource, or amount of time to help someone.", "prayer": "Lord, help me offer what I have faithfully."}, {"id": "take-40", "week": 40, "date": "2026-10-04", "dateLabel": "Sunday, 4 October 2026", "title": "Zacchaeus: When Meeting Jesus Changes Behaviour", "reference": "Luke 19:1–10", "memoryVerse": "Luke 19:10", "bigIdea": "Zacchaeus was curious enough to climb a tree, but the encounter became much more than observation. Jesus' welcome led Zacchaeus to make concrete changes involving generosity and restitution.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Do not define someone only by their past.", "prayer": "Jesus, change my heart and behaviour."}, {"id": "take-41", "week": 41, "date": "2026-10-11", "dateLabel": "Sunday, 11 October 2026", "title": "The Samaritan Woman: Jesus Meets People at Their Real Need", "reference": "John 4:1–42", "memoryVerse": "John 4:14", "bigIdea": "Jesus' conversation with the Samaritan woman crossed ethnic, religious, and social boundaries. He spoke truth about her life while also offering living water and dignity.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Speak truth kindly instead of choosing between honesty and compassion.", "prayer": "Jesus, meet the deepest needs of my heart."}, {"id": "take-42", "week": 42, "date": "2026-10-18", "dateLabel": "Sunday, 18 October 2026", "title": "Lazarus: Jesus Is Lord Over Death", "reference": "John 11", "memoryVerse": "John 11:25", "bigIdea": "John 11 contains grief, delay, questions, tears, faith, and a powerful sign. Jesus did not dismiss Martha and Mary's sorrow. He entered it, wept, and then demonstrated His authority.", "talk": "What is the main truth you want to remember from this lesson?", "action": "When grieving, speak honestly to God instead of pretending.", "prayer": "Jesus, meet me in sorrow and uncertainty."}, {"id": "take-43", "week": 43, "date": "2026-10-25", "dateLabel": "Sunday, 25 October 2026", "title": "Jesus Washes the Disciples' Feet: Greatness Through Service", "reference": "John 13:1–17", "memoryVerse": "John 13:14", "bigIdea": "On the night before His crucifixion, Jesus took the role of a servant and washed His disciples' feet. He deliberately turned status upside down and made humble service part of discipleship.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Do one unnoticed act of service this week.", "prayer": "Jesus, make me willing to serve."}, {"id": "take-44", "week": 44, "date": "2026-11-01", "dateLabel": "Sunday, 1 November 2026", "title": "The Cross: Love, Sacrifice, and Forgiveness", "reference": "Luke 23", "memoryVerse": "Romans 5:8", "bigIdea": "The crucifixion stands at the centre of the Christian message. This lesson should be taught with reverence rather than graphic detail, focusing on Jesus' willing sacrifice, forgiveness, and the meaning of the cross for sinners.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Take time to thank Jesus for His sacrifice.", "prayer": "Jesus, thank You for the cross."}, {"id": "take-45", "week": 45, "date": "2026-11-08", "dateLabel": "Sunday, 8 November 2026", "title": "The Resurrection: Jesus Is Alive", "reference": "Luke 24", "memoryVerse": "Luke 24:6", "bigIdea": "The resurrection changed frightened disciples into witnesses. The empty tomb is not presented as a private feeling but as an event that forced people to rethink what God had done in Jesus.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Begin the day with one sentence of resurrection gratitude.", "prayer": "Risen Jesus, fill me with hope."}, {"id": "take-46", "week": 46, "date": "2026-11-15", "dateLabel": "Sunday, 15 November 2026", "title": "The Great Commission: Make Disciples", "reference": "Matthew 28:16–20; Acts 1:6–11", "memoryVerse": "Matthew 28:19–20", "bigIdea": "Before Jesus' ascension, He gave His followers a mission larger than one location or generation. Making disciples includes going, teaching, baptising, and trusting Christ's continuing presence.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Pray for people in another nation or culture.", "prayer": "Lord Jesus, make me faithful to Your mission."}, {"id": "take-47", "week": 47, "date": "2026-11-22", "dateLabel": "Sunday, 22 November 2026", "title": "Pentecost: Empowered by the Holy Spirit", "reference": "Acts 2", "memoryVerse": "Acts 1:8", "bigIdea": "Pentecost marks a major moment in the life of the early church. The Holy Spirit empowered the disciples to witness, and people from many backgrounds heard the message and formed a new community.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Pray before speaking about your faith.", "prayer": "Holy Spirit, empower me to witness with courage."}, {"id": "take-48", "week": 48, "date": "2026-11-29", "dateLabel": "Sunday, 29 November 2026", "title": "Peter and John: Give What You Have", "reference": "Acts 3", "memoryVerse": "Acts 3:6", "bigIdea": "Peter and John met a man whose immediate request was money, but God used them to bring a different kind of help. The miracle became an opportunity to point attention away from themselves and toward Jesus.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Help someone this week using time or skill, not only money.", "prayer": "Lord, show me what I can give and do."}, {"id": "take-49", "week": 49, "date": "2026-12-06", "dateLabel": "Sunday, 6 December 2026", "title": "Philip and the Ethiopian Official: Explain the Good News Clearly", "reference": "Acts 8:26–40", "memoryVerse": "Acts 8:35", "bigIdea": "Philip's encounter with the Ethiopian official is a model of responsive, respectful witness. He listened, asked a question, began where the man already was, and explained Scripture in relation to Jesus.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Listen fully before answering a faith question.", "prayer": "God, make me a patient listener."}, {"id": "take-50", "week": 50, "date": "2026-12-13", "dateLabel": "Sunday, 13 December 2026", "title": "Saul Becomes Paul: Grace Can Redirect a Life", "reference": "Acts 9", "memoryVerse": "Acts 9:15", "bigIdea": "Saul was actively opposing the church when Jesus confronted him on the road to Damascus. His transformation shows that grace can interrupt a destructive direction and give a person a new purpose.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Do not assume someone's past makes change impossible.", "prayer": "Jesus, redirect anything in me that is moving the wrong way."}, {"id": "take-51", "week": 51, "date": "2026-12-20", "dateLabel": "Sunday, 20 December 2026", "title": "The Fruit of the Spirit: Character That Grows From Within", "reference": "Galatians 5:16–26", "memoryVerse": "Galatians 5:22–23", "bigIdea": "Paul contrasts self-centred living with life shaped by the Holy Spirit. The fruit of the Spirit is not a list for comparing ourselves with other people; it is a picture of character God wants to grow in believers.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Choose one fruit quality to practise deliberately this week.", "prayer": "Holy Spirit, grow Christlike character in me."}, {"id": "take-52", "week": 52, "date": "2026-12-27", "dateLabel": "Sunday, 27 December 2026", "title": "The Armour of God: Stand Firm", "reference": "Ephesians 6:10–18", "memoryVerse": "Ephesians 6:11", "bigIdea": "The final Sunday focuses on standing firm. Paul uses the image of armour to teach truth, righteousness, readiness, faith, salvation, God's word, and prayer. The emphasis is not fear but prepared, steady faith.", "talk": "What is the main truth you want to remember from this lesson?", "action": "Review one major lesson God taught you during the year.", "prayer": "Lord, help me stand firm in truth."}];
